"""SFT-only null: no RL update at all. The fixed imitation-pretrained policy is
evaluated exactly as shipped (deterministic ODE sampler). This is the floor every RL
objective must beat; it is what the papers' "SFT" rows are (RIPT-VLA Table 1,
SimpleVLA-RL Table 1, pi_RL Table 3 report their base policy the same way).
"""

_FILE = "lerobot/src/lerobot/policies/smolvla/mlsb_custom.py"

_CONTENT = '''\
# CONFIG_OVERRIDES: optimiser / update knobs your method may need. Allowed keys ONLY:
#   lr, module_lr, weight_decay, grad_clip, ppo_epochs, minibatch
# (see mlsb_rl_runtime.ALLOWED_OVERRIDES for the ranges; everything else is fixed).
CONFIG_OVERRIDES: dict = {}


class Objective(ChunkRLObjective):
    """SFT-only (no RL): the null. `trains = False` tells the harness to skip the RL
    loop entirely, so the fixed policy is evaluated as shipped."""

    group_size = 1
    trains = False

    def __init__(self, spec: PolicySpec):
        super().__init__()
        self.spec = spec

    def sample_chunk(self, sampler: ChunkSampler, gen: torch.Generator) -> ChunkSample:
        x = sampler.euler(sampler.noise(gen))
        logp = torch.zeros((sampler.batch_size, self.spec.chunk_size, self.spec.action_dim_real), device=x.device)
        return ChunkSample(actions=x, aux={}, logp_old=logp)

    def log_prob(self, sampler: ChunkSampler, aux: dict) -> tuple[Tensor, Tensor | None]:
        raise NotImplementedError("the SFT-only null never trains")

    def advantages(self, batch: RolloutBatch) -> AdvantageOutput:
        n = len(batch)
        return AdvantageOutput(adv=torch.zeros(n), mask=torch.zeros(n, dtype=torch.bool), returns=None)

    def loss(self, inp: LossInputs) -> tuple[Tensor, dict]:
        raise NotImplementedError("the SFT-only null never trains")
'''

OPS = [
